mapper.update:
merge into t_tm_assist_spec a USING (
select #{AssistSpec.materialCode,jdbcType=VARCHAR} MATERIAL_CODE, #{AssistSpec.createBy,jdbcType=VARCHAR} create_by, #{AssistSpec.createTime,jdbcType=DATE} create_time, #{AssistSpec.updateBy,jdbcType=VARCHAR} update_by, #{AssistSpec.updateTime,jdbcType=DATE} update_time, #{AssistSpec.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.MATERIAL_CODE = b.MATERIAL_CODE AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT ( a.id , a.MATERIAL_CODE , a.create_by , a.create_time , a.remark, a.del_flag ) values (SEQ_PUBLIC.NEXTVAL, b.MATERIAL_CODE , b.create_by, sysdate, b.remark, '0' )
